import{_ as s,C as r,o as t,c as d,a7 as e,b as h,w as n,a as l,E as o,a8 as p}from"./chunks/framework.BCbKzsgW.js";const f=JSON.parse('{"title":"报表统计：数据窗口、分片计算与结果发布","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/task-scheduling/scenarios/reports.md","filePath":"development/common/task-scheduling/scenarios/reports.md","lastUpdated":1793441194000}'),u={name:"development/common/task-scheduling/scenarios/reports.md"};function E(c,a,b,A,k,g){const i=r("Mermaid");return t(),d("div",null,[a[1]||(a[1]=e('<h1 id="bao-biao-tong-jishu-ju-chuang-koufen-pian-ji-suan-yu-jie-guo-fa-bu" tabindex="-1">报表统计：数据窗口、分片计算与结果发布 <a class="header-anchor" href="#bao-biao-tong-jishu-ju-chuang-koufen-pian-ji-suan-yu-jie-guo-fa-bu" aria-label="Permalink to &quot;报表统计：数据窗口、分片计算与结果发布&quot;">​</a></h1><p>日报由明确的数据窗口产生。用户登录时可以查看报表生成状态或请求补生成，但不应让首位登录用户承担全天所有报表的计算。</p><p>示例中的所有租户统一使用 <code>Asia/Shanghai</code> 时区：每天 02:00 开始生成前一天的销售报表，08:00 前交付。任务参数固定保存租户、起止时间、统计口径版本和本轮数据水位。</p><h2 id="cong-cha-xun-ye-mian-tui-dao-chi-xian-fa-bu" tabindex="-1">从查询页面推导离线发布 <a class="header-anchor" href="#cong-cha-xun-ye-mian-tui-dao-chi-xian-fa-bu" aria-label="Permalink to &quot;从查询页面推导离线发布&quot;">​</a></h2><p>假设经营者只想临时看今天的订单总额，数据量小且查询开销可控时，在线聚合可能已经足够。需求变成“每天固定时间交付昨天的正式报表，并保留可复核版本”后，计算和发布就有了独立生命周期。</p><table tabindex="0"><thead><tr><th>候选方案</th><th>合适的条件</th><th>需要承担的成本</th></tr></thead><tbody><tr><td>用户打开时实时聚合</td><td>临时查询、允许每次结果变化</td><td>请求延迟与数据库压力</td></tr><tr><td>定时覆盖一份汇总结果</td><td>允许中间覆盖且不需版本追溯的内部统计</td><td>需要解释失败重算和结果可见时点</td></tr><tr><td>独立运行、分片暂存、完整发布</td><td>要求正式交付、可修订、可恢复</td><td>运行记录、分片校验与发布指针</td></tr></tbody></table><p>本篇选择第三种。report_run 回答“这一轮算的是什么”，report_shards 回答“哪些范围已完成”，正式指针回答“用户现在应该看到哪一版”。拆分由交付和恢复要求产生，不是为了增加表的数量。</p><h2 id="ji-suan-yu-fa-bu-de-zhi-xing-shi-xu" tabindex="-1">计算与发布的执行时序 <a class="header-anchor" href="#ji-suan-yu-fa-bu-de-zhi-xing-shi-xu" aria-label="Permalink to &quot;计算与发布的执行时序&quot;">​</a></h2><p>分片计算完成只说明中间结果已保存，用户可见的版本要到发布事务成功后才改变。</p>',9)),(t(),h(p,null,{default:n(()=>[o(i,{id:"mermaid-74",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20S%20as%20%E8%B0%83%E5%BA%A6%E5%99%A8%0A%20%20%20%20participant%20D%20as%20%E6%95%B0%E6%8D%AE%E5%BA%93%0A%20%20%20%20participant%20W%20as%20%E8%AE%A1%E7%AE%97%20Worker%0A%20%20%20%20participant%20P%20as%20%E5%8F%91%E5%B8%83%E5%99%A8%0A%20%20%20%20S-%3E%3ED%3A%20%E5%90%8C%E4%BA%8B%E5%8A%A1%E5%88%9B%E5%BB%BA%E8%BF%90%E8%A1%8C%3Cbr%3E%E5%88%86%E7%89%87%E6%B8%85%E5%8D%95%E4%B8%8E%E4%BB%BB%E5%8A%A1%0A%20%20%20%20loop%20%E7%8B%AC%E7%AB%8B%E5%A4%84%E7%90%86%E5%90%84%E5%88%86%E7%89%87%0A%20%20%20%20%20%20%20%20W-%3E%3ED%3A%20%E9%A2%86%E5%8F%96%E5%88%86%E7%89%87%E4%B8%8E%E5%9B%BA%E5%AE%9A%E8%BE%93%E5%85%A5%E8%BA%AB%E4%BB%BD%0A%20%20%20%20%20%20%20%20W-%3E%3EW%3A%20%E8%AE%A1%E7%AE%97%E5%B9%B6%E7%94%9F%E6%88%90%E6%9A%82%E5%AD%98%E7%BB%93%E6%9E%9C%0A%20%20%20%20%20%20%20%20W-%3E%3ED%3A%20%E6%8C%89%E5%88%86%E7%89%87%E8%BA%AB%E4%BB%BD%E7%A1%AE%E8%AE%A4%E7%BB%93%E6%9E%9C%0A%20%20%20%20end%0A%20%20%20%20P-%3E%3ED%3A%20%E6%A0%B8%E5%AF%B9%E9%A2%84%E6%9C%9F%E5%88%86%E7%89%87%E4%B8%8E%E6%A0%A1%E9%AA%8C%E6%91%98%E8%A6%81%0A%20%20%20%20alt%20%E4%BB%8D%E6%9C%89%E7%BC%BA%E5%A4%B1%E6%88%96%E5%A4%B1%E8%B4%A5%E5%88%86%E7%89%87%0A%20%20%20%20%20%20%20%20P-%3E%3ED%3A%20%E4%BF%9D%E6%8C%81%E7%94%9F%E6%88%90%E4%B8%AD%3Cbr%3E%E5%AE%89%E6%8E%92%E7%BC%BA%E5%A4%B1%E5%88%86%E7%89%87%E6%81%A2%E5%A4%8D%0A%20%20%20%20else%20%E5%AE%8C%E6%95%B4%E4%B8%94%E6%A0%A1%E9%AA%8C%E9%80%9A%E8%BF%87%0A%20%20%20%20%20%20%20%20P-%3E%3EP%3A%20%E5%90%88%E5%B9%B6%E5%AE%8C%E6%95%B4%E4%BA%A7%E7%89%A9%0A%20%20%20%20%20%20%20%20P-%3E%3ED%3A%20%E6%9D%A1%E4%BB%B6%E5%88%87%E6%8D%A2%E5%8F%91%E5%B8%83%E6%8C%87%E9%92%88%3Cbr%3E%E5%90%8C%E4%BA%8B%E5%8A%A1%E4%BF%9D%E5%AD%98%E5%8F%91%E5%B8%83%E9%80%9A%E7%9F%A5%0A%20%20%20%20%20%20%20%20D--%3E%3EP%3A%20%E5%8F%91%E5%B8%83%E6%88%90%E5%8A%9F%E6%88%96%E4%BF%AE%E8%AE%A2%E5%86%B2%E7%AA%81%0A%20%20%20%20end%0A%20%20%20%20Note%20over%20D%2CP%3A%20%E7%94%A8%E6%88%B7%E6%9F%A5%E8%AF%A2%E8%AF%BB%E5%8F%96%E6%AD%A3%E5%BC%8F%E6%8C%87%E9%92%88%3Cbr%3E%E4%B8%8D%E8%AF%BB%E5%8F%96%E6%9C%AA%E5%8F%91%E5%B8%83%E7%9A%84%E5%88%86%E7%89%87%E7%BB%93%E6%9E%9C%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e(`<p>分片可并发处理，图中循环表示每片都要独立确认。重复成功消息不能改变预期分片集合，也不能让缺失分片自动算作完成。</p><h2 id="bao-biao-xu-qiu-yu-jiao-fu-jie-guo" tabindex="-1">报表需求与交付结果 <a class="header-anchor" href="#bao-biao-xu-qiu-yu-jiao-fu-jie-guo" aria-label="Permalink to &quot;报表需求与交付结果&quot;">​</a></h2><p>示例要求每个租户在上海时间每天 08:00 前看到完整的前一日报表。02:00 是计划开始时间，08:00 才是交付期限；业务是否允许展示旧版本、晚到数据怎样修订，都应先约定。</p><table tabindex="0"><thead><tr><th>需求</th><th>示例决策</th><th>开发约束</th></tr></thead><tbody><tr><td>展示什么</td><td>最后一次完整发布的正式版本</td><td>用户查询不直接读取中间汇总</td></tr><tr><td>没有交易怎么办</td><td>发布零数据报表并标明数据范围</td><td>不把空结果当成任务没执行</td></tr><tr><td>允许谁重跑</td><td>有权限的租户管理员或内部操作员</td><td>记录原因、版本和操作者</td></tr><tr><td>迟到数据怎么办</td><td>建立修订版本，保留原版</td><td>发布指针条件更新</td></tr><tr><td>交付延迟怎么办</td><td>展示生成状态并通知负责人</td><td>成功通知只在发布后产生</td></tr></tbody></table><h2 id="shi-jian-chuang-kou-he-ye-wu-kou-jing" tabindex="-1">时间窗口和业务口径 <a class="header-anchor" href="#shi-jian-chuang-kou-he-ye-wu-kou-jing" aria-label="Permalink to &quot;时间窗口和业务口径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>决策</th><th>示例</th><th>不明确时的后果</th></tr></thead><tbody><tr><td>时间字段</td><td>支付成功时间</td><td>下单和支付统计混淆</td></tr><tr><td>窗口边界</td><td>上海时间昨日 00:00 到今日 00:00，左闭右开</td><td>边界订单重复或遗漏</td></tr><tr><td>数据截止</td><td>02:00 生成时允许使用到哪个水位</td><td>多次读取出现不同结果</td></tr><tr><td>金额规则</td><td>实收、退款、手续费分别统计</td><td>各报表无法核对</td></tr><tr><td>修订规则</td><td>迟到数据触发新版本</td><td>旧报表被无声覆盖</td></tr></tbody></table><p>重试沿用原窗口，不重新计算“昨天”。历史重跑需要显式的日期与口径，避免恢复任务在今天处理错误窗口。</p><p>若产品按租户当地日期统计，应按每个租户的 IANA 时区分别确定窗口、计划时间与交付期限，再转换为统一时间戳调度。不能把所有租户固定在上海时间 02:00 开始，并假定它们的前一日本地窗口都已结束。</p><h2 id="shu-ju-jie-gou-yu-jie-kou" tabindex="-1">数据结构与接口 <a class="header-anchor" href="#shu-ju-jie-gou-yu-jie-kou" aria-label="Permalink to &quot;数据结构与接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>记录</th><th>关键字段与约束</th></tr></thead><tbody><tr><td><code>report_definition</code></td><td>口径版本、时区、窗口规则、输出格式、授权范围</td></tr><tr><td><code>report_run</code></td><td>租户、窗口、口径、数据水位、修订号、状态；同一运行身份唯一</td></tr><tr><td><code>report_shards</code></td><td>运行 ID、分片 ID、输入范围、结果摘要；运行内分片唯一</td></tr><tr><td><code>report_artifacts</code></td><td>运行 ID、产物 URI、校验值和有效期</td></tr><tr><td><code>report_publications</code></td><td>报表逻辑身份、当前正式运行 ID、发布代数</td></tr></tbody></table><p>创建重跑请求时返回运行 ID，查询接口返回等待、计算、校验、发布或失败阶段。下载接口按租户和报表权限授权，不因文件地址存在就允许访问。</p><p>手动重跑与自动调度使用相同的运行创建逻辑；同一请求键不能重复创建修订。正式发布指针可以独立于运行记录，避免多个修订争抢一个布尔 <code>published</code> 字段。</p><h2 id="zen-yang-chu-fa-yu-bao-cun-jin-du" tabindex="-1">怎样触发与保存进度 <a class="header-anchor" href="#zen-yang-chu-fa-yu-bao-cun-jin-du" aria-label="Permalink to &quot;怎样触发与保存进度&quot;">​</a></h2><p>日历调度器生成本轮运行记录，逻辑报表身份可采用 <code>tenant_id + window_start + metric_version</code>，运行身份再加入修订号。定时初版使用约定的初始修订，人工重算按请求键分配新修订。运行记录包含待计算分片、完成数、失败数和当前发布版本。</p><p>同一轮重复调度命中已有记录。若要修订数据，建立新的运行版本，并说明使用了哪个数据水位；不要通过更换随机任务 ID 意外生成两份互相竞争的正式报表。</p><h2 id="ren-wu-chuang-jian-yu-fen-pian-ji-suan" tabindex="-1">任务创建与分片计算 <a class="header-anchor" href="#ren-wu-chuang-jian-yu-fen-pian-ji-suan" aria-label="Permalink to &quot;任务创建与分片计算&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>调度器或重跑 API：</span></span>
<span class="line"><span>  确定窗口、口径、水位与修订号</span></span>
<span class="line"><span>  事务创建 report_run、预期分片清单与计算任务</span></span>
<span class="line"><span></span></span>
<span class="line"><span>分片 Worker：</span></span>
<span class="line"><span>  领取任务，确认运行未取消且输入版本仍有效</span></span>
<span class="line"><span>  在事务外读取固定范围，生成本次暂存结果</span></span>
<span class="line"><span>  事务校验领取资格，写入本分片结果和校验摘要</span></span>
<span class="line"><span>  确认计算任务，不通过“累计加一”重复统计完成数</span></span>
<span class="line"><span></span></span>
<span class="line"><span>汇总 Worker：</span></span>
<span class="line"><span>  核对预期分片身份与完整性</span></span>
<span class="line"><span>  合并为本轮产物，再进入发布事务</span></span></code></pre></div><p>完成数量应从唯一分片结果或受唯一约束保护的完成事件计算。一个分片的消息重复到达，不能让运行提前达到“全部完成”。</p><h2 id="1000-ge-zu-hu-de-ri-bao" tabindex="-1">1000 个租户的日报 <a class="header-anchor" href="#1000-ge-zu-hu-de-ri-bao" aria-label="Permalink to &quot;1000 个租户的日报&quot;">​</a></h2><p>调度器分批枚举 1000 个租户，为每个租户独立创建 <code>report_run</code> 和所属分片任务。这里的调度批次只用于组织枚举，不是跨租户共用的一条 <code>report_run</code>。每个租户分别计算进度、失败与发布结果，单个大租户还可以按时间段或业务分区拆开，但每个分片必须覆盖互不重叠的数据范围。</p><p>Worker 并发受查询资源限制。把 1000 个 SQL 同时提交给在线数据库，会让报表和业务请求争用连接、CPU 与磁盘。先测单任务开销，再限制总并发；必要时使用允许延迟的副本或专用分析存储。</p><p>如果使用只读副本，要记录复制延迟和业务水位。副本落后时不能把暂时没同步的订单当成最终不存在。</p><h2 id="fen-pian-du-qu-de-yi-zhi-xing" tabindex="-1">分片读取的一致性 <a class="header-anchor" href="#fen-pian-du-qu-de-yi-zhi-xing" aria-label="Permalink to &quot;分片读取的一致性&quot;">​</a></h2><p>各分片使用同一个“统计日期”并不意味着读取了同一份数据。任务运行期间仍可能有退款和补录。</p><p>可以按业务水位、不可变流水或明确的数据快照读取。PostgreSQL 的 Repeatable Read 可以为单个事务提供稳定快照，但不同 Worker 的独立事务并不会自动共享同一快照，参见<a href="https://www.postgresql.org/docs/18/transaction-iso.html" target="_blank" rel="noreferrer">事务隔离</a>。</p><p>跨 Worker 的一致快照需要额外协调；长时间维持事务也会增加数据库维护成本。没有这项设计时，应明确报表允许多大迟到与修订范围。</p><h2 id="wan-zheng-hou-zai-fa-bu" tabindex="-1">完整后再发布 <a class="header-anchor" href="#wan-zheng-hou-zai-fa-bu" aria-label="Permalink to &quot;完整后再发布&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建本轮 report_run</span></span>
<span class="line"><span>按租户或数据分区生成计算任务</span></span>
<span class="line"><span>各任务把结果写入本轮暂存区域，按分片键幂等覆盖</span></span>
<span class="line"><span>汇总器核对预期分片是否全部成功</span></span>
<span class="line"><span>校验金额、行数与数据水位</span></span>
<span class="line"><span>原子切换正式版本，保存“报表可用”通知意图</span></span></code></pre></div><p>分片重试只替换自己的结果，不能再次累加到已经完成的汇总值。用户访问到的是最后一个完整发布版本；部分失败的新版本显示生成中或失败，不伪装成完整报表。</p><h2 id="fang-zhi-jiu-xiu-ding-fu-gai-xin-fa-bu" tabindex="-1">防止旧修订覆盖新发布 <a class="header-anchor" href="#fang-zhi-jiu-xiu-ding-fu-gai-xin-fa-bu" aria-label="Permalink to &quot;防止旧修订覆盖新发布&quot;">​</a></h2><p>产物在事务外生成，正式指针在短事务中切换。下面的设计片段假定首次发布槽已创建，示例以预期发布代数防止并发覆盖：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> report_publications</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> current_run_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :validated_run_id,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    publication_version </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> publication_version </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tenant_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :tenant_id</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> report_key </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :report_key</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> publication_version </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> :expected_publication_version</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RETURNING current_run_id, publication_version;</span></span></code></pre></div><p>事务内还要锁定并校验运行已完整通过检查，保存发布结果与通知意图。竞争失败后重新读取当前修订，依据修订顺序决定是否跳过；不能无条件覆盖刚发布的新版本。</p><p>publication_version 只是对发布槽的并发检查，不能单独判断内容新旧。validated_run_id 还必须属于相同租户、窗口与口径，并通过输入水位和修订顺序检查；否则一条 SQL 成功更新也可能发布错误报表。</p><p>尚未发布的产物失败后可以重建，已经发布的下载结果保持不变。产物回收要避开正式指针和仍有效的下载引用。</p><h2 id="tong-zhi-he-bu-pao" tabindex="-1">通知和补跑 <a class="header-anchor" href="#tong-zhi-he-bu-pao" aria-label="Permalink to &quot;通知和补跑&quot;">​</a></h2><p>1000 个租户都生成完成时，可以各自生成一条可追踪的通知意图，再按渠道限速发送。频繁重算同一份报表不应重复提醒全部订阅人；发布版本与通知策略需要有独立业务键。</p><p>停机后按缺失窗口补跑，先核对业务所需的最晚交付时间。对跨多天的历史补算，保留处理水位和分片进度，控制其资源份额，给当前日报留出容量。</p><h2 id="yi-ci-fen-pian-chong-shi-yu-fa-bu-jing-zheng" tabindex="-1">一次分片重试与发布竞争 <a class="header-anchor" href="#yi-ci-fen-pian-chong-shi-yu-fa-bu-jing-zheng" aria-label="Permalink to &quot;一次分片重试与发布竞争&quot;">​</a></h2><p>假设租户 T8 的日报运行 R30 有 10 个分片，当前正式版本还是 R29：</p><table tabindex="0"><thead><tr><th>操作</th><th>中间记录</th><th>用户看到什么</th></tr></thead><tbody><tr><td>R30 的 9 个分片完成，第 10 个失败</td><td>9 份唯一结果，第 10 份待重试</td><td>仍是完整 R29，R30 显示生成中</td></tr><tr><td>第 3 个分片重复报告成功</td><td>仍是同一个 shard_id 的结果</td><td>完成数不能因此变成 10</td></tr><tr><td>第 10 个恢复，全部校验通过</td><td>R30 进入可发布状态</td><td>尚未切换前仍是 R29</td></tr><tr><td>更高修订 R31 抢先发布</td><td>指针与发布代数已推进</td><td>完整 R31</td></tr><tr><td>R30 再尝试发布</td><td>预期代数冲突，重新核对修订后退出</td><td>R31 不被旧结果覆盖</td></tr></tbody></table><p>由此可以检查一段实现是否只“看起来能重试”：如果重复处理通过总金额再次相加，或只靠完成计数器加一，就无法得到上表结果。可恢复的结果应按稳定分片身份覆盖或确认。</p><h2 id="yan-shou-yu-pai-cha-yi-ju" tabindex="-1">验收与排查依据 <a class="header-anchor" href="#yan-shou-yu-pai-cha-yi-ju" aria-label="Permalink to &quot;验收与排查依据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>应断言的结果</th></tr></thead><tbody><tr><td>同一轮重复调度</td><td>运行身份相同，不重复展开分片</td></tr><tr><td>一个分片失败，其余成功</td><td>不发布半份结果，只重试失败分片</td></tr><tr><td>分片成功但确认响应丢失</td><td>重试覆盖同一分片，不重复累加金额</td></tr><tr><td>老修订晚于新修订完成</td><td>老结果不能覆盖当前正式指针</td></tr><tr><td>数据源暂时为空或副本落后</td><td>区分真实零数据、数据未到齐和执行失败</td></tr><tr><td>租户已停用或权限撤销</td><td>停止未授权生成或下载，记录处理原因</td></tr></tbody></table><p>记录窗口、水位、预期分片集合、校验结果、发布修订与截止时间。告警同时观察交付延迟和最老未完成分片，不能只看计算进程是否存活。</p><h2 id="schedulerx-pao-pi-mo-xing-yu-bao-biao-fa-bu-tiao-jian" tabindex="-1">SchedulerX 跑批模型与报表发布条件 <a class="header-anchor" href="#schedulerx-pao-pi-mo-xing-yu-bao-biao-fa-bu-tiao-jian" aria-label="Permalink to &quot;SchedulerX 跑批模型与报表发布条件&quot;">​</a></h2><p>阿里云开发者社区中，千习的 <a href="https://developer.aliyun.com/article/866138" target="_blank" rel="noreferrer">SchedulerX 场景介绍</a>列举了周期报表生成与推送，以及数据量增长后使用分布式批处理的思路。这是一篇产品方案介绍，不能据此认定某家客户采用了本文的报表模型。其实现约束可进一步对照官方的 <a href="https://help.aliyun.com/zh/schedulerx/schedulerx-serverless/user-guide/mapreduce-model" target="_blank" rel="noreferrer">MapReduce 模型文档</a>。</p><p>官方文档说明，故障转移可能重复执行子任务，需要业务幂等；同时 <code>runReduceIfFail</code> 的默认行为允许子任务失败后仍执行 reduce。汇总回调被调用，因而不能作为“全部分片成功”的证明。接入时应核对所用客户端版本及配置，并在汇总器中检查预期分片、实际状态和结果完整性，再允许正式发布。</p><p>本文建议将大结果写入本轮暂存区，子任务只返回结果位置与校验摘要。官方还提示 reduce 收集结果会对 Master 内存形成压力，因此不能让 1000 个租户把整份报表正文都返回主节点。调度平台承担任务分发，数据水位、修订顺序和正式版本切换仍需由报表业务实现。</p><h2 id="huo-shan-yin-qing-flowxyi-lai-man-zushi-jian-dao-da-he-zi-yuan-ke-yong" tabindex="-1">火山引擎 FlowX：依赖满足、时间到达和资源可用 <a class="header-anchor" href="#huo-shan-yin-qing-flowxyi-lai-man-zushi-jian-dao-da-he-zi-yuan-ke-yong" aria-label="Permalink to &quot;火山引擎 FlowX：依赖满足、时间到达和资源可用&quot;">​</a></h2><p>火山引擎数智平台 VeDI 的 <a href="https://developer.volcengine.com/articles/7293813926247170111" target="_blank" rel="noreferrer">FlowX 工作流调度实践</a>将任务定义与按业务日期生成的实例分开，并以留存率计算说明：一个实例可能同时依赖当天和数日前的上游实例。其依赖检查、时间检查及配额管理也分别承担不同职责。<a href="https://docs.volcengine.com/docs/big-data-research-and-development-governance-suite/task-scheduling-depends-on?lang=zh" target="_blank" rel="noreferrer">DataLeap 调度依赖文档</a>则明确要求上游无失败、到达执行时间且调度资源充足。</p><p>对日报而言，“凌晨两点执行”还应落实为下面的具体条件；以下为本文设计示例：</p><table tabindex="0"><thead><tr><th>条件</th><th>开发实现</th><th>未满足时的状态</th></tr></thead><tbody><tr><td>对应业务日的订单与退款输入齐备</td><td>保存输入分区、业务日期和就绪证据</td><td>等待数据</td></tr><tr><td>到达允许生成时间</td><td>使用明确时区的计划时间</td><td>等待时间</td></tr><tr><td>获得报表资源额度</td><td>为日常运行和历史重算分别设并发预算</td><td>等待资源</td></tr><tr><td>分片完整且校验通过</td><td>核对本轮运行的结果清单</td><td>等待修复或允许发布</td></tr></tbody></table><p>FlowX 文章还介绍了通过上游成功事件重新触发依赖检查、通过探针检查外部数据，以及按时间区间配置配额。可据此将 1000 个租户的日常日报与历史补算隔离，避免补一个月历史数据占满当天交付所需的资源。任务定义之间存在依赖，不等于不同业务日期的实例可以混用数据。</p><h2 id="a-li-yun-chong-shua-shi-jianyun-xing-shi-jian-yu-shu-ju-shi-jian-fen-kai" tabindex="-1">阿里云重刷实践：运行时间与数据时间分开 <a class="header-anchor" href="#a-li-yun-chong-shua-shi-jianyun-xing-shi-jian-yu-shu-ju-shi-jian-fen-kai" aria-label="Permalink to &quot;阿里云重刷实践：运行时间与数据时间分开&quot;">​</a></h2><p>SchedulerX 的<a href="https://help.aliyun.com/zh/schedulerx/schedulerx-serverless/user-guide/update-job-outputs" target="_blank" rel="noreferrer">重刷数据说明</a>展示了今天触发一组历史日期实例的方式，并注明该能力支持的调度周期范围。它提供了区分当前运行时间和历史数据时间的具体产品例子。</p><p>本文的补跑接口应显式传入业务日期、规则版本与重跑原因，不在处理器里用“当前时间减一天”决定报表日期。重算旧日期时写入新的运行修订，验证后再切换该日期的正式指针；是否重新通知用户另作决策。同一日期允许多次尝试，但每次尝试不能把历史金额再次追加到已发布总额。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>火山引擎数智平台 VeDI：<a href="https://developer.volcengine.com/articles/7293813926247170111" target="_blank" rel="noreferrer">DataLeap 背后的工作流编排调度系统 FlowX</a></li><li>火山引擎官方文档：<a href="https://docs.volcengine.com/docs/big-data-research-and-development-governance-suite/task-scheduling-depends-on?lang=zh" target="_blank" rel="noreferrer">DataLeap 任务调度依赖</a></li><li>阿里云官方实践：<a href="https://help.aliyun.com/zh/schedulerx/schedulerx-serverless/user-guide/update-job-outputs" target="_blank" rel="noreferrer">SchedulerX 如何重刷数据</a></li><li>千习，阿里云开发者社区：<a href="https://developer.aliyun.com/article/866138" target="_blank" rel="noreferrer">SchedulerX 如何帮助用户解决分布式任务调度难题？</a></li><li>阿里云官方文档：<a href="https://help.aliyun.com/zh/schedulerx/schedulerx-serverless/user-guide/mapreduce-model" target="_blank" rel="noreferrer">SchedulerX MapReduce 模型</a></li><li>PostgreSQL 18：<a href="https://www.postgresql.org/docs/18/transaction-iso.html" target="_blank" rel="noreferrer">Transaction Isolation</a></li><li>PostgreSQL 18：<a href="https://www.postgresql.org/docs/18/sql-update.html" target="_blank" rel="noreferrer">UPDATE：条件更新与 RETURNING</a></li></ul>`,59))])}const B=s(u,[["render",E]]);export{f as __pageData,B as default};
